const order_number = $('Loop Pedidos').first().json.order_number;
const resp = ($('Consultar ParcelPanel').first() || {}).json || {};
const data = resp && resp.data ? resp.data : null;
const fuls = data && data.fulfillments ? data.fulfillments : null;
const ful = (fuls && fuls.length) ? fuls[0] : null;
function clean(s){ return (s==null?'':String(s)).replace(/[\x00-\x1F\x7F]/g,' ').trim(); }
function canonStatus(raw){ const t=(raw==null?'':String(raw)).toLowerCase().replace(/[^a-z]/g,''); if(!t) return null; if(t.indexOf('deliver')>=0) return 'delivered'; if(t.indexOf('inforeceiv')>=0) return 'info_received'; if(t.indexOf('availableforpickup')>=0 || t.indexOf('pickup')>=0) return 'pickup'; if(t.indexOf('expired')>=0) return 'expired'; if(t.indexOf('exception')>=0 || t.indexOf('attemptfail')>=0 || t.indexOf('undeliver')>=0) return 'exception'; if(t.indexOf('pending')>=0 || t.indexOf('notfound')>=0) return 'pending'; if(t.indexOf('outfordelivery')>=0 || t.indexOf('transit')>=0) return 'transit'; return null; }
function etapaDe(texto, cs){
  const t = (texto||'').toLowerCase();
  if (/customs|aduana|clearance/.test(t)) return 'aduana';
  if (/out for delivery|last mile|delivered|entregado|reparto|available for pickup|delivery in progress|delivery failed|delivery attempt/.test(t)) return 'ultima_milla';
  if (/departed|arrived|linehaul|line-haul|export|import|transit|facility|sorting|hub/.test(t)) return 'transito_nacional';
  if (/pre-?shipment|info sent|info received|acceptance|accepted|label|collected|picked up|pickup|origin/.test(t)) return 'origen';
  const c=(cs==null?'':String(cs)).toLowerCase().replace(/[^a-z]/g,'');
  if (/delivered|outfordelivery|availablefor/.test(c)) return 'ultima_milla';
  if (c.indexOf('transit')>=0) return 'transito_nacional';
  if (/inforeceiv|pending/.test(c)) return 'origen';
  return null;
}
if (!ful) { return [{ json: { order_number: order_number, status_envio: 'sin_tracking', carrier: null, dias_transito: null, etapa_actual: null } }]; }
const trackinfo = ful.trackinfo || ful.checkpoints || [];
let status_envio = canonStatus(ful.shipment_status || ful.status || ful.delivery_status);
if (!status_envio) status_envio = (trackinfo.length>0) ? 'transit' : 'pending';
let carrier = null;
if (ful.carrier && typeof ful.carrier === 'object') carrier = ful.carrier.name || ful.carrier.title || ful.carrier.slug || null;
carrier = carrier || (typeof ful.carrier==='string'?ful.carrier:null) || ful.shopify_carrier || ful.slug || null;
carrier = carrier ? clean(carrier).slice(0,60) : null;
function fechaDe(t){ return new Date(t.Date||t.date||t.checkpoint_date||t.checkpoint_time||t.created_at).getTime(); }
let latest = null;
if (trackinfo.length){ latest = trackinfo.reduce(function(a,b){ return (fechaDe(b) >= fechaDe(a)) ? b : a; }); }
let etapa_actual = null;
if (latest) { const txt = clean(latest.StatusDescription||latest.status_description||latest.message||'') + ' ' + clean(latest.Details||latest.details||''); etapa_actual = etapaDe(txt, latest.checkpoint_status || latest.status); }
if (!etapa_actual) { if (status_envio==='delivered'||status_envio==='pickup') etapa_actual='ultima_milla'; else if (status_envio==='transit') etapa_actual='transito_nacional'; else if (status_envio==='info_received'||status_envio==='pending') etapa_actual='origen'; }
if (status_envio==='delivered') etapa_actual = 'ultima_milla';
let dias_transito = null;
if (trackinfo.length>0){ const ms = trackinfo.map(fechaDe).filter(function(n){ return !isNaN(n); }); if (ms.length>0){ const primera = Math.min.apply(null, ms); const referencia = (status_envio==='delivered') ? Math.max.apply(null, ms) : Date.now(); dias_transito = Math.max(0, Math.round((referencia - primera)/86400000)); } }
return [{ json: { order_number: order_number, status_envio: status_envio, carrier: carrier, dias_transito: dias_transito, etapa_actual: etapa_actual } }];

const loopOrder = $('Loop Pedidos').first().json.order_number;
const resp = ($('Consultar ParcelPanel').first() || {}).json || {};
const data = resp && resp.data ? resp.data : null;
const fuls = data && data.fulfillments ? data.fulfillments : null;
function clean(s){ var t=String(s==null?'':s); var o=''; for(var i=0;i<t.length;i++){ var c=t.charCodeAt(i); if(c===0) continue; if(c<32 && c!==9 && c!==10 && c!==13) continue; if(c===127) continue; o+=t.charAt(i); } return o.trim(); }
function etapaDe(texto, cs){
  const t = (texto||'').toLowerCase();
  if (/customs|aduana|clearance/.test(t)) return 'aduana';
  if (/out for delivery|last mile|delivered|entregado|reparto|available for pickup|delivery in progress|delivery failed|delivery attempt/.test(t)) return 'ultima_milla';
  if (/departed|arrived|linehaul|line-haul|export|import|transit|facility|sorting|hub/.test(t)) return 'transito_nacional';
  if (/pre-?shipment|info sent|info received|acceptance|accepted|label|collected|picked up|pickup|origin/.test(t)) return 'origen';
  const c=(cs==null?'':String(cs)).toLowerCase().replace(/[^a-z]/g,'');
  if (/delivered|outfordelivery|availablefor/.test(c)) return 'ultima_milla';
  if (c.indexOf('transit')>=0) return 'transito_nacional';
  if (/inforeceiv|pending/.test(c)) return 'origen';
  return null;
}
const out = [];
if (fuls && fuls.length) {
  for (const ful of fuls) {
    const track_number = clean(ful.track_number || ful.tracking_number || '') || null;
    let carrier = null;
    if (ful.carrier && typeof ful.carrier === 'object') carrier = ful.carrier.name || ful.carrier.title || ful.carrier.slug || null;
    carrier = carrier || (typeof ful.carrier === 'string' ? ful.carrier : null) || ful.shopify_carrier || ful.slug || null;
    carrier = carrier ? clean(carrier).slice(0,60) : null;
    const trackinfo = ful.trackinfo || ful.checkpoints || [];
    for (const t of trackinfo) {
      const rawDate = t.Date||t.date||t.checkpoint_date||t.checkpoint_time||t.created_at;
      const dt = new Date(rawDate);
      if (isNaN(dt.getTime())) continue;
      const iso = dt.toISOString();
      const desc = clean(t.StatusDescription||t.status_description||t.message||t.Details||t.details||'').slice(0,300);
      const cs = t.checkpoint_status || t.status || null;
      const etapa = etapaDe(desc + ' ' + clean(t.Details||t.details||''), cs);
      const evento_key = loopOrder + '|' + iso + '|' + desc.slice(0,80);
      out.push({ json: { order_number: loopOrder, store_id: '{{STORE_ID}}', etapa: etapa, checkpoint_status: cs ? String(cs).slice(0,60) : null, descripcion: desc || null, fecha_checkpoint: iso, track_number: track_number, carrier: carrier, evento_key: evento_key } });
    }
  }
}
const seen = {}; const dedup = [];
for (const it of out) { if (seen[it.json.evento_key]) continue; seen[it.json.evento_key]=1; dedup.push(it); }
if (!dedup.length) return [{ json: { saltar: true, order_number: loopOrder } }];
return dedup;

